INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist IP ein zentrales Netzwerkprotokoll?', 2, '[{"text": "Ja", "correct": true, "because": "Ermöglicht Datenübertragung"}, {"text": "Nein", "correct": false, "because": "Es ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das IP-Protokoll?', 3, '[{"text": "Adressierung und Weiterleitung von Daten", "correct": true, "because": "Basis für Kommunikation"}, {"text": "Daten dauerhaft speichern", "correct": false, "because": "Festplattenaufgabe"}, {"text": "Grafik darstellen", "correct": false, "because": "GPU-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) IP verwendet Adressen zur Identifikation. b) Es ist nur für lokale Netzwerke.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Internet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Versionen des IP-Protokolls gibt es?', 4, '[{"text": "IPv4", "correct": true, "because": "32-Bit-Adressen"}, {"text": "Unklare Protokolle", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "IPv6", "correct": true, "because": "128-Bit-Adressen"}, {"text": "IPv5", "correct": false, "because": "Keine offizielle Version"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Netzwerk ohne IP funktionieren?', 2, '[{"text": "Ja", "correct": true, "because": "Andere Protokolle möglich"}, {"text": "Nein", "correct": false, "because": "IP weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt IP im Netzwerk?', 3, '[{"text": "Datenpakete zwischen Geräten routen", "correct": true, "because": "Verbindet Netzwerke"}, {"text": "Daten lokal speichern", "correct": false, "because": "Festplattenaufgabe"}, {"text": "Bildschirmdarstellung", "correct": false, "because": "GPU-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist IP nur für das Internet relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokale Netzwerke"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat eine IP-Adresse?', 3, '[{"text": "Geräte im Netzwerk identifizieren", "correct": true, "because": "Eindeutige Kennung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Protokolle"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) IPv4 hat 32-Bit-Adressen. b) IPv6 ist veraltet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, IPv6 aktuell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne IP im Netzwerk?', 3, '[{"text": "Datenrouting nicht möglich", "correct": true, "because": "Adressierung fehlt"}, {"text": "Netzwerk wird schneller", "correct": false, "because": "Unsinn"}, {"text": "Geräte arbeiten lokal", "correct": false, "because": "Kommunikation fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann IP ohne TCP arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "IP eigenständig"}, {"text": "Nein", "correct": false, "because": "TCP ergänzt IP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine IP-Adresse?', 3, '[{"text": "192.168.1.1", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas", "correct": false, "because": "Zu vage"}, {"text": "Netzwerkkabel", "correct": false, "because": "Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist IP nur für kabelgebundene Netzwerke relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch WLAN"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat IPv6?', 4, '[{"text": "128-Bit-Adressen", "correct": true, "because": "Mehr Adressen"}, {"text": "Keine Adressierung", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Autokonfiguration", "correct": true, "because": "Vereinfacht Setup"}, {"text": "Größere Adressräume", "correct": true, "because": "Löst IPv4-Mangel"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine IP-Adresse eindeutig sein?', 2, '[{"text": "Ja", "correct": true, "because": "Verhindert Konflikte"}, {"text": "Nein", "correct": false, "because": "Eindeutigkeit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt IP im Internet?', 3, '[{"text": "Datenpakete weltweit routen", "correct": true, "because": "Verbindet Netzwerke"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Protokolle"}, {"text": "Bildschirmdarstellung", "correct": false, "because": "GPU-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Gerät mehrere IP-Adressen haben?', 2, '[{"text": "Ja", "correct": true, "because": "Mehrere Schnittstellen"}, {"text": "Nein", "correct": false, "because": "Flexibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die IP-Adressvergabe?', 3, '[{"text": "Netzwerkgröße", "correct": true, "because": "Bestimmt Adressbereich"}, {"text": "Monitorauflösung", "correct": false, "because": "Irrelevant"}, {"text": "Tastaturlayout", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) IP arbeitet auf der Netzwerkschicht. b) Es ist nur für WLAN.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch kabelgebunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen von IP?', 3, '[{"text": "Globale Netzwerkkommunikation", "correct": true, "because": "Fördert Verbindung"}, {"text": "Maximale Isolation", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Adressierung", "correct": false, "because": "Fördert Identifikation"}]');
